130: async fn pump(
131:     shell: &mut SshShell,
132:     session: &SshSession,
133:     protocol: &mut Protocol,
134:     commands: &Receiver<TerminalCommand>,
135:     output: &SyncSender<SessionEvent>,
136:     cancelled: &AtomicBool,
137:     lifecycle: &watch::Sender<TransportState>,
138: ) -> Result<(), String> {
139:     let mut completion_seen = false;
140:     loop {
141:         if cancelled.load(Ordering::Acquire) {
142:             return Ok(());
143:         }
144: 
145:         if !completion_seen && let Some(reason) = shell.completion() {
146:             lifecycle.send_replace(TransportState::Ended(reason));
147:             completion_seen = true;
148:         }
149:         protocol.tick()?;
150:         if drain_output(shell, session, protocol, output).await? {
151:             return Ok(());
152:         }
153: 
154:         if completion_seen {
155:             tokio::time::sleep(Duration::from_millis(4)).await;
156:             continue;
157:         }
158: 
159:         while let Some(bytes) = protocol.pop_write() {
160:             match write_and_drain(
161:                 shell,
162:                 session,
163:                 protocol,
164:                 ShellWrite::Protocol(&bytes),
165:                 output,
166:                 cancelled,
167:                 lifecycle,
168:             )
169:             .await?
170:             {
171:                 WriteOutcome::Written => protocol.write_completed()?,
172:                 WriteOutcome::ShellEnded => {
173:                     completion_seen = true;
174:                     break;
175:                 }
176:                 WriteOutcome::Stopped => return Ok(()),
177:             }
178:         }
179:         if completion_seen {
180:             continue;
181:         }
182: 
183:         // Merge consecutive resize requests, but preserve their position before
184:         // the next write. No write is dequeued until this worker can own it.
185:         let mut resize = None;
186:         let mut write = None;
187:         for _ in 0..128 {
188:             match commands.try_recv() {
189:                 Ok(TerminalCommand::Resize(rows, cols)) => resize = Some((rows, cols)),
190:                 Ok(TerminalCommand::Write(bytes)) => {
191:                     if protocol.input_blocked() {
192:                         protocol.reject_input()?;
193:                     } else {
194:                         write = Some(bytes);
195:                         break;
196:                     }
197:                 }
198:                 Ok(TerminalCommand::Zmodem(control)) => {
199:                     tokio::select! {
200:                         biased;
201:                         _ = cancellation(cancelled) => return Ok(()),
202:                         result = protocol.control(session, *control) => result?,
203:                     }
204:                     break;
205:                 }
206:                 Ok(TerminalCommand::ResumeInput(id)) => protocol.resume_input(id),
207:                 Err(TryRecvError::Empty) => break,
208:                 Err(TryRecvError::Disconnected) => return Ok(()),
209:             }
210:         }
211:         if let Some((rows, cols)) = resize {
212:             let mut completion = shell.subscribe_completion();
213:             tokio::select! {
214:                 biased;
215:                 _ = cancellation(cancelled) => return Ok(()),
216:                 reason = shell_end(&mut completion) => {
217:                     lifecycle.send_replace(TransportState::Ended(reason));
218:                     completion_seen = true;
219:                     continue;
220:                 },
221:                 result = shell.resize(rows, cols) => result.map_err(|error| error.to_string())?,
222:             }
223:         }
224:         if let Some(bytes) = write {
225:             match write_and_drain(
226:                 shell,
227:                 session,
228:                 protocol,
229:                 ShellWrite::Ordinary(&bytes),
230:                 output,
231:                 cancelled,
232:                 lifecycle,
233:             )
234:             .await?
235:             {
236:                 WriteOutcome::Written => {}
237:                 WriteOutcome::ShellEnded => completion_seen = true,
238:                 WriteOutcome::Stopped => return Ok(()),
239:             }
240:         }
241:         tokio::time::sleep(Duration::from_millis(4)).await;
242:     }

245: async fn drain_output(
246:     shell: &mut SshShell,
247:     session: &SshSession,
248:     protocol: &mut Protocol,
249:     output: &SyncSender<SessionEvent>,
250: ) -> Result<bool, String> {
251:     // One retained event plus two bounded queues provide output backpressure.
252:     for _ in 0..64 {
253:         let event = if let Some(event) = protocol.output.pop_front() {
254:             event
255:         } else if protocol.wants_input() {
256:             let Some(event) = shell.try_recv() else {
257:                 break;
258:             };
259:             protocol.feed(session, event).await?;
260:             continue;
261:         } else {
262:             break;
263:         };
264:         let completed = matches!(event, SessionEvent::Exited { .. });
265:         let failed = match &event {
266:             SessionEvent::Error(message) if shell.completion().is_none() => Some(message.clone()),
267:             _ => None,
268:         };
269:         let completed =
270:             completed || matches!(event, SessionEvent::Error(_)) && shell.completion().is_some();
271:         match output.try_send(event) {
272:             Ok(()) => {
273:                 if let Some(error) = failed {
274:                     return Err(error);
275:                 }
276:                 if completed {
277:                     return Ok(true);
278:                 }
279:             }
280:             Err(TrySendError::Full(event)) => {
281:                 protocol.output.push_front(event);
282:                 break;
283:             }
284:             Err(TrySendError::Disconnected(_)) => return Ok(true),
285:         }
286:     }
287:     Ok(false)
288: }
