290: /// Preserve one write future while draining output. A failed or interrupted
291: /// write can have sent a prefix; it is never restarted or replayed.
292: #[derive(Clone, Copy)]
293: enum ShellWrite<'a> {
294:     Ordinary(&'a [u8]),
295:     Protocol(&'a [u8]),
296: }
297: 
298: enum WriteOutcome {
299:     Written,
300:     // Completion is independent of the bounded output queue. Keep draining
301:     // that queue, but never acknowledge this interrupted write as completed.
302:     ShellEnded,
303:     Stopped,
304: }
305: 
306: async fn write_and_drain(
307:     shell: &mut SshShell,
308:     session: &SshSession,
309:     protocol: &mut Protocol,
310:     write: ShellWrite<'_>,
311:     output: &SyncSender<SessionEvent>,
312:     cancelled: &AtomicBool,
313:     lifecycle: &watch::Sender<TransportState>,
314: ) -> Result<WriteOutcome, String> {
315:     let (ShellWrite::Ordinary(bytes) | ShellWrite::Protocol(bytes)) = write;
316:     let writer = shell.writer();
317:     let writing = writer.write(bytes);
318:     let mut completion = shell.subscribe_completion();
319:     tokio::pin!(writing);
320:     loop {
321:         tokio::select! {
322:             biased;
323:             _ = cancellation(cancelled) => return Ok(WriteOutcome::Stopped),
324:             reason = shell_end(&mut completion) => {
325:                 lifecycle.send_replace(TransportState::Ended(reason));
326:                 return Ok(WriteOutcome::ShellEnded);
327:             },
328:             result = &mut writing => {
329:                 if let Some(reason) = shell.completion() {
330:                     lifecycle.send_replace(TransportState::Ended(reason));
331:                     return Ok(WriteOutcome::ShellEnded);
332:                 }
333:                 return result.map(|()| WriteOutcome::Written).map_err(|error| error.to_string());
334:             },
335:             _ = tokio::time::sleep(Duration::from_millis(4)) => {
336:                 if drain_output(shell, session, protocol, output).await? {
337:                     return Ok(WriteOutcome::Stopped);
338:                 }
339:                 if matches!(write, ShellWrite::Ordinary(_)) && protocol.input_blocked() {
340:                     // A remote peer can begin Zmodem while SSH flow control
341:                     // suspends an already admitted ordinary write. Stop polling
342:                     // that future at the ownership boundary: its unknown prefix
343:                     // cannot be replayed or mixed with protocol negotiation.
344:                     protocol.interrupt_ordinary_write();
345:                     return Err("SSH_ZMODEM_INPUT_HANDOFF_INTERRUPTED".into());
346:                 }
347:             }
348:         }
349:     }

61:     pub(super) fn pop_write(&mut self) -> Option<Vec<u8>> {
62:         let bytes = self.writes.pop_front()?;
63:         self.pending_bytes = self.pending_bytes.saturating_sub(bytes.len());
64:         self.write_in_flight = true;
65:         Some(bytes)
66:     }
