108:         if let Some(id) = self.finished.take() {
109:             self.safety.publish(ZmodemUiEvent::Failed {
110:                 id,
111:                 reason: ZmodemFailure::ConnectionClosed,
112:                 uncertain: self.uploading
113:                     || self.controller.mutation_pending().load(Ordering::Acquire),
114:             })?;
115:         }
116:         let mut effects = self.controller.transport_failed();
117:         if self.interrupted_input
118:             && let Some(id) = self.blocked
119:         {
120:             effects.events.retain(|event| {
121:                 !matches!(
122:                     event,
123:                     ZmodemUiEvent::Failed { .. }
124:                         | ZmodemUiEvent::Cancelled { .. }
125:                         | ZmodemUiEvent::Finished { .. }
126:                 )
127:             });
128:             effects.events.push(ZmodemUiEvent::Failed {
129:                 id,
130:                 reason: ZmodemFailure::Protocol,
131:                 uncertain: true,
132:             });
133:             self.interrupted_input = false;
134:         }
135:         self.effects(effects)

152:     pub(super) fn resume_input(&mut self, id: Uuid) {
153:         if self.blocked == Some(id) && !self.controller.is_active() {
154:             self.resume_requested = true;
155:             self.release_input();
156:         }
157:     }
