159:     pub(super) fn transport_closed(&mut self) {
160:         self.blocked = None;
161:         self.writes.clear();
162:         self.pending_bytes = 0;
163:         self.write_in_flight = false;
164:         self.safety.active.store(false, Ordering::Release);
165:     }
166: 
167:     fn release_input(&mut self) {
168:         if self.resume_requested
169:             && !self.controller.is_active()
170:             && self.writes.is_empty()
171:             && !self.write_in_flight
172:             && self.finished.is_none()
173:         {
174:             self.blocked = None;
175:             self.input_rejection_seen = false;
176:             self.resume_requested = false;
177:             self.safety.active.store(false, Ordering::Release);
178:         }

181:     fn effects(&mut self, effects: ZmodemOutput) -> Result<(), String> {
182:         if let Some(lease) = self.controller.lease_id() {
183:             if self.blocked != Some(lease) {
184:                 self.input_rejection_seen = false;
185:                 self.resume_requested = false;
186:             }
187:             self.blocked = Some(lease);
188:             self.safety.active.store(true, Ordering::Release);
189:         }
190:         if !effects.terminal.is_empty() {
191:             self.push_event(SessionEvent::Data(effects.terminal))?;
192:         }
193:         for event in effects.events {
194:             if let ZmodemUiEvent::Finished { id } = event {
195:                 // The codec can request its final OO trailer and report
196:                 // Finished in one step. Do not publish that result until the
197:                 // actual SSH write completes; a failed write stays a failure.
198:                 self.finished = Some(id);
199:                 continue;
200:             }
201:             if matches!(event, ZmodemUiEvent::UploadRequested { .. }) {
202:                 self.uploading = true;
203:             } else if matches!(event, ZmodemUiEvent::DownloadOffered { .. }) {
204:                 self.uploading = false;
205:             }
206:             if let ZmodemUiEvent::UploadRequested { id }
207:             | ZmodemUiEvent::DownloadOffered { id, .. } = &event
208:             {
209:                 if self.blocked != Some(*id) {
210:                     self.input_rejection_seen = false;
211:                     self.resume_requested = false;
212:                 }
213:                 self.blocked = Some(*id);
214:                 self.safety.active.store(true, Ordering::Release);
215:             }
216:             // Results have a bounded, shared mailbox: a stopped bridge cannot
217:             // strand its terminal UI behind a full byte-output receiver.
218:             self.safety.publish(event)?;
219:         }
220:         for bytes in effects.writes {
221:             if bytes.is_empty() {
222:                 continue;
223:             }
224:             self.pending_bytes = self
225:                 .pending_bytes
226:                 .checked_add(bytes.len())
227:                 .filter(|bytes| *bytes <= MAX_PROTOCOL_PENDING_BYTES)
228:                 .ok_or("ZMODEM_PROTOCOL_OUTPUT_LIMIT")?;
229:             if self.writes.len() >= MAX_PROTOCOL_WRITES {
230:                 return Err("ZMODEM_PROTOCOL_OUTPUT_LIMIT".into());
231:             }
232:             self.writes.push_back(bytes);
233:         }
234:         self.finish_if_flushed()?;
235:         Ok(())
236:     }
