238:     fn finish_if_flushed(&mut self) -> Result<(), String> {
239:         if self.writes.is_empty()
240:             && !self.write_in_flight
241:             && let Some(id) = self.finished.take()
242:         {
243:             self.safety.publish(ZmodemUiEvent::Finished { id })?;
244:         }
245:         Ok(())

