20: /// The bridge publishes ownership before an event can wait in a full UI queue.
21: /// Acknowledging an older uncertainty cannot clear a newer, unread result.
22: #[derive(Default)]
23: pub(crate) struct Safety {
24:     pub(crate) active: AtomicBool,
25:     pub(crate) uncertain_epoch: AtomicU64,
26:     publication_running: Arc<AtomicBool>,
27:     acknowledged_epoch: AtomicU64,
28:     events: Mutex<VecDeque<ZmodemUiEvent>>,
29: }
30: 
31: impl Safety {
32:     pub(crate) fn new(publication_running: Arc<AtomicBool>) -> Self {
33:         Self {
34:             publication_running,
35:             ..Self::default()
36:         }
37:     }
38: 
39:     pub(crate) fn close_busy(&self) -> bool {
40:         self.active.load(Ordering::Acquire)
41:             || self.publication_running.load(Ordering::Acquire)
42:             || self.uncertain_epoch.load(Ordering::Acquire)
43:                 != self.acknowledged_epoch.load(Ordering::Acquire)
44:     }
45: 
46:     pub(crate) fn publish(&self, event: ZmodemUiEvent) -> Result<(), String> {
47:         // Keep the close hold even if the bounded notification queue cannot
48:         // retain this result. An unread uncertainty is never acknowledged.
49:         if matches!(
50:             event,
51:             ZmodemUiEvent::Failed {
52:                 uncertain: true,
53:                 ..
54:             } | ZmodemUiEvent::Cancelled {
55:                 uncertain: true,
56:                 ..
57:             }
58:         ) {
59:             self.uncertain_epoch.fetch_add(1, Ordering::AcqRel);
60:         }
61:         let mut events = self
62:             .events
63:             .lock()
64:             .map_err(|_| "ZMODEM_UI_STATE_UNAVAILABLE")?;
65:         if let ZmodemUiEvent::Progress { id, .. } = &event
66:             && matches!(events.back(), Some(ZmodemUiEvent::Progress { id: previous, .. }) if previous == id)
67:         {
68:             events.pop_back();
69:         }
70:         if events.len() >= 256 {
71:             return Err("ZMODEM_UI_STATE_LIMIT".into());
72:         }
73:         events.push_back(event);
74:         Ok(())
75:     }
76: 
77:     pub(crate) fn take_events(&self) -> Result<Vec<ZmodemUiEvent>, String> {
78:         let mut events = self
79:             .events
80:             .lock()
81:             .map_err(|_| "ZMODEM_UI_STATE_UNAVAILABLE")?;
82:         let count = events.len().min(64);
83:         Ok(events.drain(..count).collect())
84:     }
85: }
