392:     fn end_zmodem(&mut self, id: Uuid, feedback: Message, uncertain: bool) {
393:         if uncertain {
394:             self.zmodem.seen_uncertain_epoch = self.zmodem.seen_uncertain_epoch.saturating_add(1);
395:         }
396:         if let Some(current) = self
397:             .zmodem
398:             .current
399:             .as_mut()
400:             .filter(|current| current.id == id)
401:         {
402:             if !matches!(current.stage, Stage::Ended) {
403:                 current.stage = Stage::Ended;
404:                 current.picker = None;
405:                 current.feedback = feedback.clone();
406:             }
407:             if uncertain {
408:                 let (zh, en) = current.summary.translations();
409:                 let (zh_result, en_result) = feedback.translations();
410:                 self.zmodem.unresolved.insert(
411:                     id,
412:                     Message::new(
413:                         format!("{zh}\n\n{zh_result}"),
414:                         format!("{en}\n\n{en_result}"),
415:                     ),
416:                 );
417:                 self.zmodem.acknowledge_review = None;
418:             }
419:         } else if uncertain {
420:             // An older result still protects close even when a newer offer is
421:             // already visible. Do not replace that new offer with an old one.
422:             self.zmodem.unresolved.insert(id, feedback);
423:             self.zmodem.acknowledge_review = None;
424:         }
425:         // Receive leases precede the first file offer, so there may be no
426:         // card (or only a previous card). Only the bridge can release its
427:         // latch, after checking this exact ID and draining protocol writes.
428:         if !self.zmodem.pending_resumes.contains(&id) {
429:             if self.zmodem.pending_resumes.len() < MAX_PENDING_RESUMES {
430:                 self.zmodem.pending_resumes.push_back(id);
431:             } else {
432:                 // Preserve queued handoffs and the bridge's input fence if
433:                 // notification traffic exceeds the bounded handoff budget.
434:                 self.input_error = Some("ZMODEM_INPUT_HANDOFF_LIMIT".into());
435:             }
436:         }
437:     }
