439:     fn zmodem_control(&mut self, control: ZmodemControl, cx: &mut Context<Self>) {
440:         let Some(current) = self.zmodem.current.as_mut() else {
441:             return;
442:         };
443:         if matches!(current.stage, Stage::Ended | Stage::Cancelling) {
444:             return;
445:         }
446:         let current_action = match &control {
447:             ZmodemControl::PrepareUpload { transfer, .. } => {
448:                 *transfer == current.id && matches!(current.stage, Stage::Upload)
449:             }
450:             ZmodemControl::PrepareReceive {
451:                 transfer, offer, ..
452:             } => {
453:                 *transfer == current.id
454:                     && matches!(current.stage, Stage::Download { offer: current_offer, .. } if current_offer == *offer)
455:             }
456:             ZmodemControl::Confirm { transfer, review } => {
457:                 *transfer == current.id
458:                     && matches!(current.stage, Stage::Review { review: current_review } if current_review == *review)
459:             }
460:             ZmodemControl::Cancel { transfer } => *transfer == current.id,
461:         };
462:         if !current_action {
463:             return;
464:         }
465:         let cancelling = matches!(control, ZmodemControl::Cancel { .. });
466:         match self
467:             .outgoing
468:             .try_send(TerminalCommand::Zmodem(Box::new(control)))
469:         {
470:             Ok(()) => {
471:                 current.stage = if cancelling {
472:                     Stage::Cancelling
473:                 } else {
474:                     Stage::Running
475:                 };
476:                 current.picker = None;
477:                 current.feedback = Message::new("正在处理本次操作…", "Processing this operation…");
478:             }
479:             Err(mpsc::TrySendError::Full(_)) => {
480:                 current.feedback = Message::new(
481:                     "终端操作队列已满，本次操作未提交；请稍后重新点击。",
482:                     "The terminal operation queue is full. This action was not submitted; try again.",
483:                 );
484:             }
485:             Err(mpsc::TrySendError::Disconnected(_)) => {
486:                 current.feedback = Message::new(
487:                     "终端连接已关闭，本次操作未提交。",
488:                     "The terminal connection is closed. This action was not submitted.",
489:                 );
490:             }
491:         }
492:         cx.notify();
493:     }

574:     fn acknowledge_zmodem_outcomes(&mut self, cx: &mut Context<Self>) {
575:         let epoch = self.zmodem.seen_uncertain_epoch;
576:         let ids: Vec<_> = self.zmodem.unresolved.keys().copied().collect();
577:         if self.zmodem_input_blocked()
578:             || self
579:                 .zmodem
580:                 .safety
581:                 .publication_running
582:                 .load(Ordering::Acquire)
583:             || self.zmodem.safety.uncertain_epoch.load(Ordering::Acquire) != epoch
584:         {
585:             self.zmodem.acknowledge_review = None;
586:             return;
587:         }
588:         if self.zmodem.acknowledge_review.as_ref() == Some(&(epoch, ids.clone())) {
589:             // This acknowledges only the displayed uncertainty for window
590:             // closing; it performs no filesystem cleanup or reservation reset.
591:             self.zmodem
592:                 .safety
593:                 .acknowledged_epoch
594:                 .store(epoch, Ordering::Release);
595:             self.zmodem.unresolved.clear();
596:             self.zmodem.acknowledge_review = None;
597:         } else {
598:             self.zmodem.acknowledge_review = Some((epoch, ids));
599:         }
600:         cx.notify();
601:     }

